import "./css/Festval_CardItem.css";


const Festval_card_item = ({cardItem}) => {

  const {title, eventstartdate, eventenddate, addr1, addr2, firstimage , mapx, mapy,tel} = cardItem;
  
    return(
        <div className='card_list_item'>            
            <img className='media_header' src={firstimage} alt="com" />
            <div className="media_item">              
              <ul className="media_info">
                <li className="media_alram">
                    <span>준비중</span>
                </li>              
                <li className="media_title">
                    {title}
                </li>                
                <li className="media_date">
                  <span className="sub">기간</span>                  
                  <span>{eventstartdate}</span>~<span>{eventenddate}</span>                  
                </li>
                <li className="media_address">
                  <span className="sub">장소</span>                  
                  <span>{addr1}{addr2}</span>                  
                </li>
                <li className="media_link">
                  <a className="media_map" href="#">{mapx}<br />{mapy}</a>
                  <a className="media_home" href="#">{tel}</a>
                </li>
              </ul>              
            </div>
        </div>
    );
};

export default Festval_card_item;
